// Shor period finding
(()=>{const el=$("#s-shor");el.innerHTML=`<h4>Live simulation · Shor’s algorithm: period finding</h4><label class="mono">N <select id="n"><option>15<option>21<option>35<option>77</select></label> <label class="mono">a <input type="number" id="a" value="7" min="2" max="76"></label> <button id="go">Find period</button><div class="cols"></div><p class="mono"></p>`;const gcd=(x,y)=>y?gcd(y,x%y):x;
$("#go",el).onclick=()=>{const N=+$("#n",el).value,a=+$("#a",el).value;let v=1,q=[],r=0;for(let i=0;i<36;i++){q.push(v);v=v*a%N;if(!r&&v==1)r=i+1}$(".cols",el).innerHTML=q.map((u,i)=>`<div class="col ${r&&i%r==0?"k":""}"><b>${u}</b><i>x=${i}</i></div>`).join("");let m=`f(x)=${a}^x mod ${N}. `;if(gcd(a,N)>1)m+=`gcd(a,N)=${gcd(a,N)} is already a factor (lucky guess).`;else if(!r)m+="No period found.";else{m+=`Period r=${r}. `;const hh=q[r/2],f=gcd(hh-1,N);m+=r%2==0&&f>1&&f<N?`Factors: gcd(a^(r/2)−1,N)=${f}, gcd(a^(r/2)+1,N)=${gcd(hh+1,N)} → ${N} = ${f} × ${N/f}. A quantum computer finds r via the QFT exponentially faster.`:"Odd or trivial period – pick another a."}$(".mono",el).textContent=m};$("#go",el).click()})();
