(()=>{const el=$("#s-rabi");el.innerHTML=`<h4>Live simulation · Rabi oscillation & decoherence (how a physical gate works)</h4><label class="mono">Drive Ω <input type="range" id="o" min="5" max="40" value="15"></label> <label class="mono">Coherence T2 <input type="range" id="t" min="1" max="30" value="12"></label><p class="mono">A pulse rotates the qubit: P(1)=½(1−cos Ωt·e^(−t/T2)). The first peak is a π-pulse, i.e. an X gate; decoherence damps the curve and causes gate errors.</p><canvas width="520" height="200"></canvas>`;const x=$("canvas",el).getContext("2d");function dr(){const O=$("#o",el).value/10,T=$("#t",el).value/2;x.clearRect(0,0,520,200);x.strokeStyle="#22d3ee";x.beginPath();for(let i=0;i<=520;i++){const t=i/52,p=.5*(1-Math.cos(O*t)*Math.exp(-t/T));x[i?"lineTo":"moveTo"](i,190-p*180)}x.stroke();x.fillStyle="#a3abcf";x.fillText("P(|1⟩) vs time",8,14)}dr();el.oninput=dr})();
